import axios from 'axios';
import * as TYPES from '../actions/types';

import {interceptor} from './interceptor';
interceptor();

export const fetchPosDetaisByMerchantId = (id) => dispatch => {
    axios({
        method:'GET',
        url:`${TYPES.BASE_URL}/pos-details/merchant-id/${id}`
    }).then(response => {
        dispatch({
            type:TYPES.GET_POS_DETAILS_BY_MERCHANT_ID,
            payload:response
        })
    }).catch(err => {
        dispatch({
            type:TYPES.GET_POS_DETAILS_BY_MERCHANT_ID_ERROR,
            payload:err.response
        })
    })
}

export const fetchAllPosDetails = (date) => dispatch => {
    if(date){
        axios({
            method:'GET',
            url:`${TYPES.BASE_URL}/pos-details/${date}?all&all`
        }).then(response => {
            dispatch({
                type:TYPES.GET_ALL_POS_DETAILS,
                payload:response
            })
        }).catch(err => {
            dispatch({
                type:TYPES.GET_ALL_POS_DETAILS_ERROR,
                payload:err.response
            })
        })
    }else{
        axios({
            method:'GET',
            url:`${TYPES.BASE_URL}/pos-details`
        }).then(response => {
            dispatch({
                type:TYPES.GET_ALL_POS_DETAILS,
                payload:response
            })
        }).catch(err => {
            dispatch({
                type:TYPES.GET_ALL_POS_DETAILS_ERROR,
                payload:err.response
            })
        })
    }
    
}